# Last step. Hash every input and output. Do not edit this file after it runs.
# Usage: python -I work/scripts/write_manifest_i1.py
import hashlib
import json
import subprocess
from pathlib import Path

ROOT = Path(".").resolve()
H = "T3h-afon-zone-faces/run-20261118-113413/work"

RESEARCH = [
    "TASK.md",
    "brief.md",
    "templates/result.md",
    "ref/tasks/T3h-afon-zone-faces/decision.md",
    "ref/tasks/T3h-afon-zone-faces/run-20261118-122604-review/review.md",
    "ref/analysis/button-af/AFON-MENU-RESEARCH.md",
    "ref/analysis/decompiled-main/functions/611c7785.c",
    f"ref/tasks/{H}/result.md",
    f"ref/tasks/{H}/out/faces.md",
    f"ref/tasks/{H}/out/design.md",
    f"ref/tasks/{H}/out/static-faces-h1.txt",
    f"ref/tasks/{H}/out/disasm-7785-h1.txt",
    f"ref/tasks/{H}/out/disasm-611f81aa-h1.txt",
    f"ref/tasks/{H}/out/disasm-611f8437-h1.txt",
    f"ref/tasks/{H}/scripts/accept_h1.mjs",
    f"ref/tasks/{H}/scripts/exp_faces_h1.mjs",
    f"ref/tasks/{H}/scripts/exp_faces_h2.mjs",
    f"ref/tasks/{H}/scripts/session_h3.mjs",
    f"ref/tasks/{H}/scripts/build_overlay_h1.py",
    f"ref/tasks/{H}/scripts/run_logged.mjs",
    f"ref/tasks/{H}/scripts/static_faces_h1.py",
    "ref/tasks/T3c-afon-editor-routing/run-20261118-073716/work/scripts/route_page_a3.mjs",
    "om-emu/emu/src/util/bytes.mjs",
    "om-emu/emu/src/core/mem.mjs",
    "om-emu/emu/src/lab/sim.mjs",
    "om-emu/emu/src/lab/resources.mjs",
]


def rel(path):
    s = str(path).replace("\\", "/")
    root = str(ROOT).replace("\\", "/")
    if s.lower().startswith(root.lower() + "/"):
        s = s[len(root) + 1:]
    return s


def sha_file(path):
    data = Path(path).read_bytes()
    return hashlib.sha256(data).hexdigest(), len(data)


def add_exec(store, path, digest, nbytes, where):
    key = rel(path)
    row = store.setdefault(key, {"sha256": digest, "bytes": nbytes, "where": []})
    if row["sha256"] != digest:
        row.setdefault("conflicts", []).append({"sha256": digest, "bytes": nbytes, "where": where})
    row["where"].append(where)


exec_hashes = {}
for path in sorted(Path("work/out").rglob("*.jsonl")):
    for line in path.read_text(encoding="utf-8").splitlines():
        if '"helper-hashes"' not in line:
            continue
        rec = json.loads(line)
        if rec.get("step") != "helper-hashes":
            continue
        where = rel(path) + "#helper-hashes"
        for item in rec.get("helpers", []) + rec.get("resources", []):
            add_exec(exec_hashes, item["path"], item["sha256"], item.get("bytes"), where)

strings = Path("work/out/strings-i1.txt").read_text(encoding="utf-8")
head = strings.splitlines()[0]
if head.startswith("helpers "):
    for item in json.loads(head[len("helpers "):]):
        add_exec(exec_hashes, item["path"], item["sha256"], item.get("bytes"), "work/out/strings-i1.txt#helpers")

for exit_path in sorted(Path("work/out/cmd").glob("*.exit"), key=lambda p: int(p.name.split(".")[0])):
    doc = json.loads(exit_path.read_text(encoding="utf-8"))
    for item in doc.get("scripts") or []:
        add_exec(exec_hashes, item["path"], item["sha256"], item.get("bytes"), rel(exit_path))

missing = [p for p in RESEARCH if not Path(p).exists()]
if missing:
    raise SystemExit("missing research files: " + ", ".join(missing))

inputs = []
seen = set()
for key, rec in sorted(exec_hashes.items()):
    if key.startswith("work/"):
        continue
    later, nbytes = sha_file(key)
    inputs.append({
        "path": key,
        "sha256": rec["sha256"],
        "bytes": rec["bytes"],
        "hashed": "execution",
        "execution_where": rec["where"],
        "later_sha256": later,
        "later_matches": later == rec["sha256"] and nbytes == rec["bytes"],
    })
    seen.add(key)
for path in RESEARCH:
    key = rel(path)
    if key in seen:
        continue
    digest, nbytes = sha_file(path)
    inputs.append({"path": key, "sha256": digest, "bytes": nbytes, "hashed": "later"})
    seen.add(key)

sources = []
for path in sorted(Path("work/scripts").glob("*")):
    if not path.is_file():
        continue
    digest, nbytes = sha_file(path)
    key = rel(path)
    row = {"path": key, "sha256": digest, "bytes": nbytes, "hashed": "later"}
    if key in exec_hashes:
        row["hashed"] = "execution"
        row["execution_sha256"] = exec_hashes[key]["sha256"]
        row["execution_where"] = exec_hashes[key]["where"]
        row["later_matches"] = digest == exec_hashes[key]["sha256"]
    sources.append(row)

outputs = []
out_files = [Path("work/result.md")]
out_files.extend(p for p in Path("work/out").rglob("*") if p.is_file())
for path in sorted(out_files, key=lambda p: rel(p)):
    digest, nbytes = sha_file(path)
    outputs.append({"path": rel(path), "sha256": digest, "bytes": nbytes, "hashed": "later"})

commands = []
for exit_path in sorted(Path("work/out/cmd").glob("*.exit"), key=lambda p: int(p.name.split(".")[0])):
    doc = json.loads(exit_path.read_text(encoding="utf-8"))
    n = exit_path.name.split(".")[0]
    commands.append({
        "id": n,
        "spawn": doc.get("spawn"),
        "status": doc.get("status"),
        "start": doc.get("start"),
        "end": doc.get("end"),
        "exit_file": rel(exit_path),
        "hashed": "later",
    })
commands.append({
    "id": "13",
    "spawn": "python -I work/scripts/write_manifest_i1.py",
    "status": None,
    "note": "This process. The wrapper writes work/out/cmd/13.exit after the manifest file is closed, so that exit file is not an entry above.",
})

def tool(cmd):
    try:
        return subprocess.check_output(cmd, text=True, stderr=subprocess.STDOUT).strip()
    except Exception as e:
        return str(e)

brief_sha, _ = sha_file("brief.md")
manifest = {
    "task": "T3i",
    "brief_sha256": brief_sha,
    "brief_hashed": "later",
    "inputs": inputs,
    "sources": sources,
    "outputs": outputs,
    "commands": commands,
    "tool_versions": {"node26": tool(["node26", "--version"]), "python": tool(["python", "--version"])},
    "note": "execution hashes come from JSONL helper-hashes records, strings-i1.txt, and cmd/*.exit script records. later hashes were taken by this script. The manifest file itself is not an output entry.",
}
Path("work/evidence-manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
bad = [r["path"] for r in inputs + sources if r.get("later_matches") is False]
print("inputs", len(inputs), "sources", len(sources), "outputs", len(outputs), "mismatches", bad)
